  values ('ember-ambient-glow-lamp', 'Ember Ambient Glow Lamp', 'Sunset tones for evening focus.', 'A small rechargeable lamp that bathes the wall behind your desk in warm amber light. Built to reduce eye strain during late sessions and to make your workspace feel like somewhere you want to be.', 'lighting', 299900, null, array['https://images.unsplash.com/photo-1616400619175-5beda3a17896?w=1200&q=75&auto=format&fit=crop', 'https://images.unsplash.com/photo-1593062096033-9a26b09da705?w=1200&q=75&auto=format&fit=crop', 'https://images.unsplash.com/photo-1484788984921-03950022c9ef?w=1200&q=75&auto=format&fit=crop']::text[], array['Rechargeable, 8-hour battery', 'Stepless dimming', 'Warm 2200K glow', 'Aluminium body']::text[], '{"Battery":"4000 mAh, USB-C","Height":"24 cm","Colour temp.":"2200K","Warranty":"1 year"}'::jsonb, 'New', false, true, '2026-10-18T10:00:00Z')
  on conflict (slug) do update set price = excluded.price
  returning id
)
