select p.id, v.name, v.swatch, v.stock, v.position from p, (values
  ('Amber', '#d08a3b', 40, 0),
  ('Rose', '#c97a72', 33, 1)
) as v(name, swatch, stock, position)
on conflict (product_id, name) do nothing;

